import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"VeilChat: A Messenger With No Server to Breach","description":"The story of building VeilChat — a serverless P2P messenger with end-to-end encryption, direct TCP connections and zero metadata.","frontmatter":{"title":"VeilChat: A Messenger With No Server to Breach","description":"The story of building VeilChat — a serverless P2P messenger with end-to-end encryption, direct TCP connections and zero metadata."},"headers":[],"relativePath":"en/vibe-stories/story-2/index.md","filePath":"en/vibe-stories/story-2/index.md"}`),a={name:`en/vibe-stories/story-2/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="veilchat-a-messenger-with-no-server-to-breach" tabindex="-1">VeilChat: A Messenger With No Server to Breach <a class="header-anchor" href="#veilchat-a-messenger-with-no-server-to-breach" aria-label="Permalink to “VeilChat: A Messenger With No Server to Breach”">​</a></h1><p>Every mainstream messenger quietly relies on infrastructure that knows <em>who</em> talks to <em>whom</em>, even when it cannot read the content. Metadata is the business model. I wanted to know how far I could push in the opposite direction — so I built <strong><a href="https://github.com/Godde3s/veilchat" target="_blank" rel="noreferrer">VeilChat</a></strong>: two peers, one direct TCP connection, and an encrypted channel that never touches a third party.</p><h2 id="the-design-constraint" tabindex="-1">The design constraint <a class="header-anchor" href="#the-design-constraint" aria-label="Permalink to “The design constraint”">​</a></h2><p>No accounts. No servers. No phone numbers. No metadata. That constraint decided everything. There is no signup flow because there is nothing to sign up to; there is no message relay because there is no message relay company. Two peers discover each other — over the LAN or a direct dial — run a mutually-authenticated key exchange, and from that moment every byte on the wire is an AEAD-encrypted frame.</p><h2 id="the-hard-parts" tabindex="-1">The hard parts <a class="header-anchor" href="#the-hard-parts" aria-label="Permalink to “The hard parts”">​</a></h2><ul><li><strong>Key exchange done right</strong> — an X25519 handshake with mutual authentication, HKDF-derived session keys and transcript checks, so neither a passive listener nor an active impostor learns anything.</li><li><strong>The wire protocol</strong> — a 24-byte nonce header plus ChaCha20-Poly1305 frames: replay protection and integrity without a single byte of plaintext metadata.</li><li><strong>NAT-friendly delivery</strong> — LAN discovery for the common case, direct dial for everything else, with the handshake retried until both sides confirm.</li></ul><h2 id="what-it-proves" tabindex="-1">What it proves <a class="header-anchor" href="#what-it-proves" aria-label="Permalink to “What it proves”">​</a></h2><p>VeilChat is roughly 1,000 lines of readable, auditable Python — CLI and importable library. I built the hard parts of a messenger from scratch: key management, handshake design, wire protocol, encrypted delivery. It is the difference between <em>using</em> cryptography libraries and <em>designing with</em> them, and it is the project I reach for when someone asks whether I understand security as engineering rather than as a checklist.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};